#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve(){
    ll n, m; cin >> n >> m;
    vector<ll> cloud(m);
    for(ll i = 0; i < m; i++) cin >> cloud[i];
    sort(cloud.begin(), cloud.end());
    ll l{cloud[0]-1}, r{n-cloud[m-1]}, mg{};
    for(ll i = 1; i < m; i++){
        ll g{cloud[i] - cloud[i-1]-1};
        ll gd{max(0ll, g - (l+r))};
        mg = max(mg, gd);
    }
    
    ll ans{min(2*l + r + mg, 2*r+l+mg)};
    cout << ans;
}

int main() {
	int t; cin >> t;
	while(t--){
	    solve();
	    cout << "\n";
	}

}
